from __future__ import annotations

from . import ImageFile


class StubImageFile(ImageFile.StubImageFile):
    def _open(self):
        offset = self.fp.tell()

        if not self._accept(self.fp.read(self._read_bytes)):
            msg = self._error_message
            raise SyntaxError(msg)

        self.fp.seek(offset)

        # make something up
        self._mode = "F"
        self._size = 1, 1

        loader = self._load()
        if loader:
            loader.open(self)


def make_save_handler(format_name, get_handler):
    def _save(im, fp, filename):
        handler = get_handler()
        if handler is None or not hasattr(handler, "save"):
            msg = f"{format_name} save handler not installed"
            raise OSError(msg)
        handler.save(im, fp, filename)

    return _save
